dtsPropsFor.AccountDetailDrawer:
/** The previewed company; null closes the Drawer. */
account: MaskedAccount | null;
onClose: () => void;
/** Switch the page to the Contacts scope filtered by this account. Omit to hide the button. */
onViewContacts?: (account: MaskedAccount) => void;

dtsPropsFor.AccountFilterPanel:
query: AccountQuery;
onChange: (next: AccountQuery) => void;
/** Live per-option counts keyed `${field}:${value}` (from POST /account-search/facets). Optional. */
counts?: Map<string, number>;
/** The Prospect/Account scope switch, hosted at the top of the sidebar. */
scopeSwitch?: React.ReactNode;

dtsPropsFor.AccountsTable:
accounts: MaskedAccount[];
loading: boolean;
onOpen: (a: MaskedAccount) => void;
/** Reserved for symmetry with the Contacts grid; DataTable reads [data-density] from an ancestor. */
density?: string;

dtsPropsFor.BulkActionBar:
/** The selection model (explicit ids OR "all N matching"); drives the targeted BulkSelection. */
selection: ProspectBulkSelection;
/** The page's active search query — the `criteria` for select-all-matching + searchCount. */
query: ContactQuery;
/** The full selected masked rows (drives the reveal targets in explicit-id mode). */
selectedContacts: MaskedContact[];
/** Selected ids that can actually be revealed (hasEmail && !isRevealed) — explicit-id mode only. */
revealableIds: string[];
/** The workspace tags (for the add/remove-tags pickers). */
tags: Tag[];
/** A row-level action to open with the (already seeded) single-row selection; null = none pending. */
requestedAction?: RowBulkAction | null;
/** Fired once a requestedAction has been opened, so the parent can reset it. */
onRequestHandled?: () => void;
/** Fired with the ids that were revealed so the parent can flip rows + clear the selection. */
onRevealed: (revealedIds: string[]) => void;
/** Fired after any non-reveal mutation so the parent can reload the grid + clear the selection. */
onMutated?: () => void;
/** Hide the "Select all N matching" escalation — for surfaces not backed by the workspace search query. */
hideSelectAllMatching?: boolean;
/** Extra surface-specific actions rendered in the bar (e.g. a list's "Remove from list"). Explicit-ids only. */
extraActions?: React.ReactNode;

dtsPropsFor.BulkRevealJobDialog:
open: boolean;
onClose: () => void;
/** The active search query — the job reveals every VISIBLE contact matching it (resolved server-side). */
criteria: ContactQuery;
revealType?: RevealType;
/** Called after a run finishes so the parent can refresh the grid + clear the selection. */
onDone?: () => void;

dtsPropsFor.FacetTypeahead:
field: FacetKey;
label: string;
selected: string[];
onAdd: (value: string) => void;
onRemove: (value: string) => void;

dtsPropsFor.FilterPanel:
query: ContactQuery;
onChange: (next: ContactQuery) => void;
/** Live per-option counts keyed `${field}:${value}` (from POST /search/facets). Optional. */
counts?: Map<string, number>;
/** Teammates (+ a "Me" entry the page prepends) for the Owner facet. */
owners?: OwnerOption[];
/** Optional rail content (saved + recent searches) rendered under the head, before the groups. */
header?: React.ReactNode;
/** The Prospect/Account scope switch, hosted at the top of the sidebar. */
scopeSwitch?: React.ReactNode;

dtsPropsFor.FilterRail:
filter: ProspectFilter;
onChange: (next: ProspectFilter) => void;
/** The loaded rows — facet value sets (department, country) are derived from these. */
contacts: MaskedContact[];
/** Apply a VALIDATED filter compiled by the AI NL box. Optional so the rail still renders where AI isn't wired. */
onAiApply?: (query: ContactQuery) => void;
/** The workspace's tags — rendered as toggleable filter facets. */
tags?: Tag[];

dtsPropsFor.ProspectToolbar:
/** The active search query; `query.sort` drives the sort control. */
query: ContactQuery;
/** Commit a query change (e.g. a new sort) back to the page. */
onChange: (q: ContactQuery) => void;
/** All toggleable result columns (key + display label). */
columns: { key: string; label: string }[];
/** The keys currently shown. */
visibleColumns: string[];
/** Commit the next visible-column key set. */
onVisibleColumnsChange: (keys: string[]) => void;

dtsPropsFor.QuickViewDrawer:
/** The previewed row; null closes the Drawer. */
contact: MaskedContact | null;
onClose: () => void;
/** Hand off to the full RecordDetail. Omit to hide the button. */
onOpenFull?: () => void;

dtsPropsFor.RecordDetail:
/** The selected row; null closes the Drawer. */
contact: MaskedContact | null;
onClose: () => void;
onRevealed: (contactId: string) => void;
/** Called when the record's tags change in a way that affects the workspace tag list (a new tag created). */
onTagsChanged?: () => void;

dtsPropsFor.RevealCell:
contact: MaskedContact;
field: "email" | "phone";
/** Flip the row's coarse isRevealed flag after a successful reveal (keeps other surfaces in sync). */
onRevealed?: (contactId: string) => void;

dtsPropsFor.RevealDialog:
contact: MaskedContact;
revealType: RevealType;
open: boolean;
onClose: () => void;
/** Fired after a successful reveal so the parent can flip the row to revealed. */
onRevealed: (contactId: string) => void;

dtsPropsFor.RowActions:
/** The row this menu acts on (drives the Email-until-revealed gate). */
contact: MaskedContact;
onAddToList?: () => void;
onTag?: () => void;
onChangeStatus?: () => void;
/** Open the contact's LinkedIn. Omit when the row has no LinkedIn url — the item is then hidden. */
onOpenLinkedin?: () => void;

dtsPropsFor.SaveSearchPanel:
/** The filter set the rail currently has applied — what "Save search" persists. */
currentQuery: ContactQuery;
/** Re-apply a saved search: the caller feeds its filters back into the prospect rail (setText/setFilters). */
onApply: (filters: ContactQuery) => void;

dtsPropsFor.TagChip:
name: string;
color: TagColor | string;
/** Toggled state when the chip is used as a filter facet. */
active?: boolean;
/** When set the chip becomes a button (filter facet / picker option). */
onClick?: () => void;
/** When set, renders a trailing × that removes the tag without triggering onClick. */
onRemove?: () => void;

dtsPropsFor.TagPicker:
recordId: string;
entity?: TaggableEntity;
/** The tags currently assigned to this record (owned by the parent so chips re-render on change). */
assigned: PickerTag[];
/** Apply the next assigned-tag list. A functional updater (prev → next) so concurrent assign/unassign/create mutations compose instead of clobbering each other. */
onChange: (updater: (prev: PickerTag[]) => PickerTag[]) => void;
/** Called after a NEW workspace tag is created, so callers can refresh a workspace-wide tag list. */
onTagCreated?: () => void;
